//! Psalms (Zabur) resolver — the Jewish edition, in Hebrew numbering.
//!
//! Reads `psalms/{psalm}.json`, one file per psalm, generated by
//! `scripts/build-psalms.py` from eBible.org's public-domain exports:
//!
//! - `he` — the Hebrew Masoretic text, whose verses these are;
//! - `en` — JPS 1917, the Jewish English translation;
//! - `ar` — the Smith & Van Dyck Arabic (1865);
//! - `en_kjv` and `en_web` — the King James Version and the World English
//!   Bible.
//!
//! Search matches `ar` and `en`, as for every other source. The Hebrew, KJV
//! and WEB are returned, not searched.
//!
//! # Versification
//!
//! Hebrew numbering counts a psalm's title as a verse of its own. `PS:3:1` is
//! "A Psalm of David, when he fled from Absalom his son" and nothing more; the
//! prayer begins at `PS:3:2`. Where the title shares a verse with the opening
//! line, as in Psalm 23, the numbers agree with English Bibles. There are 2527
//! verses here against their 2461, and every record says which English verse
//! numbers it corresponds to in `english_verses`.
//!
//! The translations are English-numbered upstream, so the build re-cuts them:
//! JPS exactly, at the Hebrew verse numbers it carries inline, and the other
//! three at the psalm title. Where a title spans two Hebrew verses (Psalms 51,
//! 52, 54 and 60), only JPS can be divided inside it, and the second title
//! verse carries an empty `ar`, `en_kjv` and `en_web`.
//!
//! # Why only Psalms
//!
//! Psalms is a single book, so it fits the grammar as it stands: `PS:23:1` is
//! Psalm 23, verse 1, and `PS::N` counts verses across the whole book. The
//! Torah and the rest of the Bible need a third level — book, chapter, verse —
//! which the grammar does not have yet; see `docs/bible-plan.md`.

use crate::ast::Reference;
use crate::error::Error;
use crate::record::Record;
use crate::repo::Repository;
use crate::sources::{locate, total, Source};
use serde::Deserialize;
use serde_json::Value;
use std::sync::Arc;

const PSALM_COUNT: u32 = 150;
const DIR: &str = "psalms";

/// Verse count of each psalm, in Hebrew numbering. Lets `PS::N` find its psalm
/// without reading the other 149 files; a test checks every entry against the
/// data.
const PSALM_VERSES: [u32; PSALM_COUNT as usize] = [
    6, 12, 9, 9, 13, 11, 18, 10, 21, 18, 7, 9, 6, 7, 5, 11, 15, 51, 15, 10, 14, 32, 6, 10, 22, 12,
    14, 9, 11, 13, 25, 11, 22, 23, 28, 13, 40, 23, 14, 18, 14, 12, 5, 27, 18, 12, 10, 15, 21, 23,
    21, 11, 7, 9, 24, 14, 12, 12, 18, 14, 9, 13, 12, 11, 14, 20, 8, 36, 37, 6, 24, 20, 28, 23, 11,
    13, 21, 72, 13, 20, 17, 8, 19, 13, 14, 17, 7, 19, 53, 17, 16, 16, 5, 23, 11, 13, 12, 9, 9, 5,
    8, 29, 22, 35, 45, 48, 43, 14, 31, 7, 10, 10, 9, 8, 18, 19, 2, 29, 176, 7, 8, 9, 4, 8, 5, 6, 5,
    6, 8, 8, 3, 18, 3, 3, 21, 26, 9, 8, 24, 14, 10, 8, 12, 15, 21, 10, 20, 14, 9, 6,
];

/// Verses in the whole book. Derived, so it cannot drift from the table.
const VERSE_COUNT: u32 = total(&PSALM_VERSES);

/// `PS` — the Psalms of David, the Zabur.
#[derive(Debug, Default)]
pub struct Psalms;

#[derive(Debug, Deserialize)]
struct Psalm {
    verses: Vec<Verse>,
}

#[derive(Debug, Deserialize)]
struct Verse {
    verse: u32,
    he: String,
    ar: String,
    en: String,
    kjv: String,
    web: String,
    /// The verse number(s) English Bibles give this verse — one for most, two
    /// where Hebrew joins English verses (13:6 is English 13:5–6).
    english: Vec<u32>,
}

impl Source for Psalms {
    fn code(&self) -> &str {
        "PS"
    }

    fn name(&self) -> &str {
        "Psalms (Zabur)"
    }

    fn aliases(&self) -> Vec<&str> {
        vec!["ZABUR", "PSALMS"]
    }

    fn total(&self, _repo: &mut Repository) -> Result<Option<u32>, Error> {
        Ok(Some(VERSE_COUNT))
    }

    fn resolve(
        &self,
        repo: &mut Repository,
        reference: &Reference,
        out: &mut Vec<Record>,
    ) -> Result<(), Error> {
        // `PS::100` — count verses across the whole book.
        let Some(number) = reference.primary else {
            return self.resolve_flat(repo, reference, out);
        };

        if number == 0 || number > PSALM_COUNT {
            return Err(Error::ReferenceNotFound {
                detail: format!("Psalm {number} (Psalms has 1..=150)"),
            });
        }

        let psalm = Self::load(repo, number)?;
        let count = u32::try_from(psalm.verses.len()).map_err(|_| Error::InvalidDataFile {
            path: format!("{DIR}/{number}.json"),
            detail: "implausible verse count".into(),
        })?;

        for verse in reference.expand(count)? {
            out.push(self.record(&psalm, number, verse)?);
        }

        Ok(())
    }
}

impl Psalms {
    fn load(repo: &mut Repository, number: u32) -> Result<Arc<Psalm>, Error> {
        repo.load(format!("{DIR}/{number}.json"))
    }

    /// One verse as a record. Files are ordered and complete, but the verse is
    /// found by its number rather than trusted to its position.
    fn record(&self, psalm: &Psalm, number: u32, verse: u32) -> Result<Record, Error> {
        let found = psalm
            .verses
            .iter()
            .find(|v| v.verse == verse)
            .ok_or_else(|| Error::ReferenceNotFound {
                detail: format!("PS:{number}:{verse}"),
            })?;

        let english: Vec<Value> = found.english.iter().map(|&v| v.into()).collect();
        Ok(Record {
            source: self.code().to_string(),
            collection: self.name().to_string(),
            extra: [
                ("psalm".to_string(), number.into()),
                ("verse".to_string(), verse.into()),
                ("english_verses".to_string(), Value::Array(english)),
                (
                    "bible_ref".to_string(),
                    bible_ref("PSA", number, &found.english).into(),
                ),
                ("he".to_string(), found.he.clone().into()),
                ("en_kjv".to_string(), found.kjv.clone().into()),
                ("en_web".to_string(), found.web.clone().into()),
            ]
            .into_iter()
            .collect(),
            ar: found.ar.clone(),
            emlaei: String::new(),
            en: found.en.clone(),
        })
    }

    /// `PS::N` — the N-th verse of the book, 1..=2527, read from the ordinary
    /// psalm files so it is the same text `PS:psalm:verse` returns.
    fn resolve_flat(
        &self,
        repo: &mut Repository,
        reference: &Reference,
        out: &mut Vec<Record>,
    ) -> Result<(), Error> {
        for global in reference.expand(VERSE_COUNT)? {
            let (number, verse) =
                locate(&PSALM_VERSES, global).ok_or_else(|| Error::ReferenceNotFound {
                    detail: format!("PS::{global}"),
                })?;

            let psalm = Self::load(repo, number)?;
            let mut record = self.record(&psalm, number, verse)?;
            record.extra.insert("number".to_string(), global.into());
            record.extra.insert("numbering".to_string(), "book".into());
            out.push(record);
        }

        Ok(())
    }
}

/// The same passage in the Bible, as a query: `OT:PSA:3:1`, or
/// `OT:PSA:13:5-6` where Hebrew joins two English verses. Shared with the
/// Torah, whose verses move between chapters too.
pub(crate) fn bible_ref(book: &str, chapter: u32, english: &[u32]) -> String {
    match english {
        [] => format!("OT:{book}:{chapter}"),
        [only] => format!("OT:{book}:{chapter}:{only}"),
        [first, .., last] => format!("OT:{book}:{chapter}:{first}-{last}"),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bible_refs_are_queries() {
        assert_eq!(bible_ref("PSA", 3, &[1]), "OT:PSA:3:1");
        assert_eq!(bible_ref("PSA", 13, &[5, 6]), "OT:PSA:13:5-6");
        for query in [bible_ref("PSA", 3, &[1]), bible_ref("PSA", 13, &[5, 6])] {
            assert!(crate::parse(&query).is_ok(), "{query}");
        }
    }

    #[test]
    fn the_table_covers_the_whole_book() {
        assert_eq!(PSALM_VERSES.len(), 150);
        assert_eq!(VERSE_COUNT, 2527);
        // The longest and the shortest.
        assert_eq!(PSALM_VERSES[118], 176);
        assert_eq!(PSALM_VERSES[116], 2);
        // A title of its own makes Psalm 3 one verse longer than in English.
        assert_eq!(PSALM_VERSES[2], 9);
    }

    #[test]
    fn locate_maps_the_edges_of_the_book() {
        assert_eq!(locate(&PSALM_VERSES, 1), Some((1, 1)));
        assert_eq!(locate(&PSALM_VERSES, 6), Some((1, 6)));
        assert_eq!(locate(&PSALM_VERSES, 7), Some((2, 1)));
        assert_eq!(locate(&PSALM_VERSES, VERSE_COUNT), Some((150, 6)));
        assert_eq!(locate(&PSALM_VERSES, VERSE_COUNT + 1), None);
        assert_eq!(locate(&PSALM_VERSES, 0), None);
    }
}
